with scored as (select *, avg(discount_pct) over (partition by promo_code order by discount_pct asc, id asc rows between 3 preceding and current row) last4_avg_discount_pct, count(discount_pct) over (partition by promo_code order by discount_pct asc, id asc rows between 3 preceding and current row) last4_count_discount_pct, sum(discount_pct) over (partition by promo_code order by discount_pct asc, id asc rows between 3 preceding and current row) last4_sum_discount_pct, max(discount_pct) over (partition by promo_code order by discount_pct asc, id asc rows between 3 preceding and current row) last4_max_discount_pct from promotions), base as (select id, channel, starts_on, last4_avg_discount_pct, last4_count_discount_pct, last4_max_discount_pct - last4_avg_discount_pct last4_max_discount_pct_minus_last4_avg_discount_pct, coalesce(channel, 'OTHER') channel_filled from scored where ends_on >= to_date('2023-09-11') and last4_avg_discount_pct between 0.2 and 0.3), base_promotions as (select id, starts_on, last4_avg_discount_pct, last4_count_discount_pct, last4_max_discount_pct_minus_last4_avg_discount_pct, channel_filled, last4_count_discount_pct * last4_avg_discount_pct last4_count_discount_pct_times_last4_avg_discount_pct from base where starts_on >= date '2023-04-05' and channel is not null), filtered as (select id, last4_avg_discount_pct, last4_count_discount_pct, last4_max_discount_pct_minus_last4_avg_discount_pct, channel_filled, last4_count_discount_pct_times_last4_avg_discount_pct, round(last4_max_discount_pct_minus_last4_avg_discount_pct, 0) last4_max_discount_pct_minus_last4_avg_discount_pct_rounded from base_promotions where starts_on >= to_date('2023-06-15') and starts_on between '2024-07-01' and '2024-10-24'), cleaned as (select *, round(last4_count_discount_pct_times_last4_avg_discount_pct, 1) last4_count_discount_pct_times_last4_avg_discount_pct_rounded from filtered where last4_count_discount_pct_times_last4_avg_discount_pct between 35 and 70), valid as (select id, last4_avg_discount_pct, last4_count_discount_pct, last4_max_discount_pct_minus_last4_avg_discount_pct, last4_count_discount_pct_times_last4_avg_discount_pct, last4_count_discount_pct_times_last4_avg_discount_pct_rounded, last4_max_discount_pct_minus_last4_avg_discount_pct_rounded + last4_count_discount_pct_times_last4_avg_discount_pct last4_max_discount_pct_minus_last4_avg_discount_pct_rounded_plus_last4_count_discount_pct_times_last4_avg_discount_pct from cleaned where last4_avg_discount_pct >= 0.13), grouped as (select case when last4_count_discount_pct_times_last4_avg_discount_pct_rounded >= 87 then 'PREMIUM' else 'STANDARD' end as last4_count_discount_pct_times_last4_avg_discount_pct_rounded_tier, case when last4_count_discount_pct_times_last4_avg_discount_pct >= 65 then 'LARGE' else 'SMALL' end as last4_count_discount_pct_times_last4_avg_discount_pct_tier, min(last4_count_discount_pct) as min_last4_count_discount_pct, count(distinct id) as distinct_ids, count(distinct id) as distinct_ids_2, percentile_approx(last4_max_discount_pct_minus_last4_avg_discount_pct, array(0.25, 0.5, 0.75)) as last4_max_discount_pct_minus_last4_avg_discount_pct_quartiles, grouping(case when last4_count_discount_pct_times_last4_avg_discount_pct_rounded >= 87 then 'PREMIUM' else 'STANDARD' end) as gid from valid group by grouping sets ((case when last4_count_discount_pct_times_last4_avg_discount_pct_rounded >= 87 then 'PREMIUM' else 'STANDARD' end, case when last4_count_discount_pct_times_last4_avg_discount_pct >= 65 then 'LARGE' else 'SMALL' end), (case when last4_count_discount_pct_times_last4_avg_discount_pct_rounded >= 87 then 'PREMIUM' else 'STANDARD' end))) select last4_count_discount_pct_times_last4_avg_discount_pct_rounded_tier, min_last4_count_discount_pct, distinct_ids, last4_max_discount_pct_minus_last4_avg_discount_pct_quartiles from grouped order by distinct_ids asc;
